def slug(s):return re.sub(r'[^a-z0-9]+','-',s.lower()).strip('-')
def wrap(scene):
    svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100">'+scene+'</svg>'
    ET.fromstring(svg)
    if re.search(r'<(?:script|image|text|foreignObject)|href\s*=|onload\s*=',svg,re.I): raise ValueError('Unsafe SVG')
    return svg

def main():
    assert len(NEW)==10 and len(REDRAW)==24,(len(NEW),len(REDRAW))
    d=json.loads(subprocess.check_output(['node','tools/v68-inspect.mjs'],cwd=R)); names={e['name'].casefold():e['id'] for e in d['items']};recipes=d['recipes']; old={e['name']:e for e in json.loads((R/'shared/v61-art-manifest.json').read_text())['icons']}
    prior=set()
    for v in [63,65,66,67]:
        prior.update(e['name'] for e in json.loads((R/f'shared/v{v}-approved.json').read_text())['redrawn_v61'])
    new=[];redrawn=[];pack=[];rec=[];art={};pairs=set()
    for name,(a,b,category,scene) in NEW.items():
        assert name.casefold() not in names,name
        assert a.casefold() in names and b.casefold() in names,(a,b)
        pair='|'.join(sorted([names[a.casefold()],names[b.casefold()]]))
        assert pair not in recipes and pair not in pairs,(name,pair)
        pairs.add(pair);id='organic68:'+slug(name);svg=wrap(scene);path=R/'client/assets/v68/new'/f'{slug(name)}.svg';path.parent.mkdir(parents=True,exist_ok=True);path.write_text(svg)
        pack.append({'id':id,'name':name,'category':category,'summary':f'{name}: {a} + {b}','iconFamily':'organic'});rec.append([names[a.casefold()],names[b.casefold()],id]);art[name.casefold()]=svg
        new.append({'name':name,'id':id,'ingredients':[a,b],'path':str(path.relative_to(R)),'sha256':hashlib.sha256(svg.encode()).hexdigest(),'art_mode':'bespoke-silhouette'})
    for name,scene in REDRAW.items():
        assert name in old and name not in prior,name
        svg=wrap(scene);path=R/'client/assets/v68/redrawn-v61'/f'{slug(name)}.svg';path.parent.mkdir(parents=True,exist_ok=True);path.write_text(svg);art[name.casefold()]=svg
        redrawn.append({'name':name,'id':old[name]['id'],'path':str(path.relative_to(R)),'sha256':hashlib.sha256(svg.encode()).hexdigest(),'art_mode':'bespoke-silhouette','previous_art_mode':'motif-composite'})
    (R/'client/src/organic-pack-v68.js').write_text('/* V68: editorial discoveries */\nexport const ORGANIC_V68 = '+json.dumps({'items':pack,'recipes':rec},separators=(',',':'))+';\n')
    (R/'client/src/organic-art-v68.js').write_text('/* V68: individual drawn subject silhouettes */\nexport const ORGANIC_ART_V68 = '+json.dumps(art,separators=(',',':'))+';\n')
    (R/'shared/v68-approved.json').write_text(json.dumps({'version':68,'new_items':new,'redrawn_v61':redrawn},indent=2)+'\n')
    print('V68 authored',len(new),'new and',len(redrawn),'redrawn art pieces')
if __name__=='__main__':main()
